<?php
declare(strict_types=1);
ini_set('display_errors','0');
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: same-origin');
header('X-Frame-Options: DENY');
header('Cache-Control: no-store');
define('PRIVATE_DIR', __DIR__.'/private');
define('UPLOAD_DIR', PRIVATE_DIR.'/uploads');
const JFLAGS = JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR;
function sendJson($v,int $status=200): never {http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($v,JFLAGS);exit;}
function fail(string $message,int $status=400): never {sendJson(['error'=>$message],$status);}
function getConfig(): array {return require PRIVATE_DIR.'/config.php';}
function db(): PDO {static $p=null;if($p)return $p;$c=getConfig();if(str_starts_with($c['db_name'],'PASTE_')||str_starts_with($c['db_user'],'PASTE_'))throw new RuntimeException('Database configuration incomplete');$p=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return $p;}
function readData(string $file): object {return json_decode(file_get_contents(PRIVATE_DIR.'/'.$file),false,512,JSON_THROW_ON_ERROR);}
function data(string $name): object {$q=db()->prepare('SELECT body FROM cms_content WHERE name=?');$q->execute([$name]);$r=$q->fetchColumn();return $r===false?readData('seed.json'):json_decode($r,false,512,JSON_THROW_ON_ERROR);}
function writeData(string $name,string $body): void {$q=db()->prepare('INSERT INTO cms_content(name,body) VALUES(?,?) ON DUPLICATE KEY UPDATE body=VALUES(body)');$q->execute([$name,$body]);}
function csrf(): void {$origin=$_SERVER['HTTP_ORIGIN']??'';$host=$_SERVER['HTTP_HOST']??'';if($host===''||!hash_equals('https://'.$host,$origin))fail('Invalid request origin. Use the HTTPS website address.',403);}
function readBody(int $max): string {$declared=(int)($_SERVER['CONTENT_LENGTH']??0);if($declared>$max)fail('Request too large',413);$f=fopen('php://input','rb');$body=stream_get_contents($f,$max+1);fclose($f);if($body===false||strlen($body)>$max)fail('Request too large',413);return $body;}
function readJson(int $max=800000) {return json_decode(readBody($max),false,512,JSON_THROW_ON_ERROR);}
function beginSession(): void {if(session_status()===PHP_SESSION_ACTIVE)return;ini_set('session.use_strict_mode','1');ini_set('session.use_only_cookies','1');ini_set('session.gc_maxlifetime','3600');session_name('HOSPITAL_ADMIN');session_set_cookie_params(['lifetime'=>3600,'path'=>'/','secure'=>true,'httponly'=>true,'samesite'=>'Strict']);session_cache_limiter('');session_start();}
function adminRequired(): void {beginSession();if(empty($_SESSION['admin'])||($_SESSION['expires']??0)<time()){$_SESSION=[];session_destroy();fail('Sign in required',401);}}
function checkRate(): void {$ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'unknown');$bucket=intdiv(time(),900);$p=db();$q=$p->prepare('INSERT INTO cms_attempts(ip,bucket,n) VALUES(?,?,1) ON DUPLICATE KEY UPDATE n=n+1');$q->execute([$ip,$bucket]);$q=$p->prepare('SELECT n FROM cms_attempts WHERE ip=? AND bucket=?');$q->execute([$ip,$bucket]);if((int)$q->fetchColumn()>8)fail('Too many attempts. Try again in 15 minutes.',429);}
function urlOk(string $s): bool {return strlen($s)<=2048&&filter_var($s,FILTER_VALIDATE_URL)!==false&&strtolower((string)parse_url($s,PHP_URL_SCHEME))==='https';}
function mediaOk(string $s): bool {return $s===''||preg_match('~^assets/[A-Za-z0-9_.-]+$~D',$s)===1||preg_match('~^/media/[a-f0-9]{32}$~D',$s)===1||urlOk($s);}
function linkOk(string $s,string $key): bool {if($s==='')return true;if($key==='href'&&preg_match('~^#(?:home|about|departments|services|infrastructure|gallery|contact)$~D',$s))return true;return urlOk($s);}
function invalid(string $s): never {throw new InvalidArgumentException($s);}
function validateSizes($m,array $allowed): void {if(!is_object($m))invalid('Invalid image dimensions');foreach(get_object_vars($m) as $k=>$q){if(!in_array($k,$allowed,true)||!is_object($q)||array_diff(array_keys(get_object_vars($q)),['width','height','fit','x','y']))invalid('Invalid image size');foreach(['width','height'] as $a){$v=$q->$a??null;if(!is_string($v)||($v!==''&&(!preg_match('/^\d{1,4}$/D',$v)||(int)$v<1||(int)$v>2400)))invalid('Image size must be 1–2400 px');}if(!in_array($q->fit??null,['','cover','contain','fill'],true))invalid('Invalid image fit');foreach(['x','y'] as $a){if(isset($q->$a)&&(!is_int($q->$a)||$q->$a< -200||$q->$a>($a==='x'?1600:300)))invalid('Invalid image position');}}}
function validateText($m,array $allowed): void {if(!is_object($m))invalid('Invalid text styles');foreach(get_object_vars($m) as $k=>$q){if(!in_array($k,$allowed,true)||!is_object($q)||array_diff(array_keys(get_object_vars($q)),['size','color','font']))invalid('Invalid text style');if(isset($q->size)&&(!is_string($q->size)||($q->size!==''&&(!preg_match('/^\d{2}$/D',$q->size)||(int)$q->size<10||(int)$q->size>64))))invalid('Font size must be 10–64 px');if(isset($q->color)&&(!is_string($q->color)||($q->color!==''&&!preg_match('/^#[0-9a-f]{6}$/iD',$q->color))))invalid('Invalid text color');if(isset($q->font)&&!in_array($q->font,['','Arial','Georgia','Verdana','Tahoma','Trebuchet MS','Times New Roman','system-ui'],true))invalid('Invalid font');}}
function validate($x,$t,string $k=''): void {
 if(is_string($t)){if(!is_string($x)||strlen($x)>60000)invalid('Invalid text: '.$k);if($k==='scrollDuration'&&(!preg_match('/^\d{3,4}$/D',$x)||(int)$x<100||(int)$x>2000))invalid('Animation duration must be 100–2000 ms');if(in_array($k,['href','mapUrl'],true)&&!linkOk($x,$k))invalid('Invalid link');if(in_array($k,['logo','video','galleryVideo','poster','banner','image','wellnessImage'],true)&&!mediaOk($x))invalid('Invalid media link');return;}
 if(is_array($t)){if(!is_array($x)||count($x)>100)invalid('Invalid list: '.$k);if($k==='specialties'&&!count($x))invalid('Keep at least one speciality');if($k==='specialties'||$k==='faqs'){foreach($x as $row){$template=$t[0];$n=count($template);if(!is_array($row)||count($row)<$n||count($row)>$n+($k==='specialties'?2:1))invalid('Invalid row');for($i=0;$i<$n;$i++)validate($row[$i],$template[$i],$k==='specialties'&&$i===2?'image':'');if($k==='specialties'&&count($row)>4)validateSizes($row[4],['image']);if($k==='specialties'&&count($row)>5)validateText($row[5],['name','description','facilities']);if($k==='faqs'&&count($row)>2)validateText($row[2],['question','answer']);}}else{foreach($x as $v)validate($v,$t[0]??'',$k);}return;}
 if(!is_object($x)||!is_object($t))invalid('Invalid section: '.$k);$fields=get_object_vars($t);$keys=array_keys(get_object_vars($x));if(array_diff($keys,array_merge(array_keys($fields),['mediaSizes','textStyles']))||array_diff(array_keys($fields),$keys))invalid('Invalid section: '.$k);
 if(property_exists($x,'mediaSizes')){$allowed=array_values(array_intersect(array_keys($fields),['logo','poster','banner','image','wellnessImage']));if(!$allowed)invalid('Unexpected image settings');validateSizes($x->mediaSizes,$allowed);}
 if(property_exists($x,'textStyles')){$allowed=[];foreach($fields as $f=>$v)if(is_string($v)&&!in_array($f,['logo','video','galleryVideo','poster','banner','image','wellnessImage','mapUrl','href','scrollDuration'],true))$allowed[]=$f;validateText($x->textStyles,$allowed);}
 foreach($fields as $f=>$v)validate($x->$f,$v,$f);
}
function installed(): bool {try{return (bool)db()->query('SELECT id FROM cms_admin WHERE id=1')->fetchColumn();}catch(PDOException $e){if(($e->errorInfo[1]??0)===1146)return false;throw $e;}}
function setupPage(string $message='',bool $done=false): never {header('Content-Type: text/html; charset=utf-8');$esc=htmlspecialchars($message,ENT_QUOTES,'UTF-8');echo '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hospital CMS setup</title><style>body{font:16px system-ui;background:#edf4f7;color:#173247;padding:24px}main{max-width:450px;margin:6vh auto;background:white;border:1px solid #cadbe4;padding:28px;border-radius:16px}label{display:block;margin-top:16px}input,button{box-sizing:border-box;width:100%;padding:12px;margin-top:5px;border:1px solid #bdcfd8;border-radius:8px;font:inherit}button{background:#087e83;color:white;font-weight:bold;border:0;margin-top:20px}a{color:#087e83}</style><main><h1>Hospital CMS setup</h1><p>'.$esc.'</p>';if($done){echo '<a href="/admin">Open admin panel</a>';}else{echo '<p>Use the installation key from private/config.php. This installer locks after the first successful setup.</p><form method="post"><label>Installation key<input name="key" type="password" required autocomplete="off"></label><label>Admin password (16–64 characters)<input name="password" type="password" required minlength="16" maxlength="64" autocomplete="new-password"></label><label>Confirm password<input name="confirm" type="password" required minlength="16" maxlength="64" autocomplete="new-password"></label><button>Initialize database and create admin</button></form>';}echo '</main></html>';exit;}
function setup(string $method): never {
 $c=getConfig();$key=(string)$c['setup_key'];if(strlen($key)<24||str_starts_with($key,'REPLACE_'))setupPage('First configure MySQL and a unique installation key in private/config.php.',true);
 if(installed())setupPage('Already installed. Setup is locked.',true);if($method==='GET')setupPage('Create your administrator account.');if($method!=='POST')fail('Method not allowed',405);
 $given=$_POST['key']??'';$pw=$_POST['password']??'';$confirm=$_POST['confirm']??'';if(!is_string($given)||!hash_equals($key,$given)){http_response_code(403);setupPage('Invalid installation key.');}if(!is_string($pw)||strlen($pw)<16||strlen($pw)>64||$pw!==$confirm)setupPage('Use a matching password of 16–64 characters.');
 $p=db();foreach(explode(';',file_get_contents(PRIVATE_DIR.'/schema.sql')) as $sql){if(trim($sql)!=='')$p->exec($sql);}
 $seed=readData('seed.json');validate($seed,readData('defaults.json'));$body=json_encode($seed,JFLAGS);$p->beginTransaction();try{$q=$p->prepare('INSERT INTO cms_admin(id,username,password_hash) VALUES(1,?,?)');$q->execute(['admin',password_hash($pw,PASSWORD_DEFAULT)]);$q=$p->prepare('INSERT IGNORE INTO cms_content(name,body) VALUES(?,?)');$q->execute(['draft',$body]);$q->execute(['published',$body]);$p->commit();}catch(Throwable $e){$p->rollBack();throw $e;}
 setupPage('Installation successful. Sign in as admin with the password you chose.',true);
}
function upload(): never {
 $b=readBody(20*1024*1024);if($b==='')fail('Choose a file');$mime=(new finfo(FILEINFO_MIME_TYPE))->buffer($b);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif','video/mp4'=>'mp4'];if(!isset($types[$mime]))fail('Only JPEG, PNG, GIF, WebP and MP4 allowed');if(str_starts_with($mime,'image/')&&!@getimagesizefromstring($b))fail('Invalid image');if($mime==='video/mp4'&&substr($b,4,4)!=='ftyp')fail('Invalid MP4 file');
 if(!is_dir(UPLOAD_DIR)&&!mkdir(UPLOAD_DIR,0750,true))fail('Upload folder unavailable',500);$id=bin2hex(random_bytes(16));$file=UPLOAD_DIR.'/'.$id.'.'.$types[$mime];if(file_put_contents($file,$b,LOCK_EX)!==strlen($b)){@unlink($file);fail('Could not save upload',500);}try{$q=db()->prepare('INSERT INTO cms_media(id,mime,bytes) VALUES(?,?,?)');$q->execute([$id,$mime,strlen($b)]);}catch(Throwable $e){@unlink($file);throw $e;}sendJson(['url'=>'/media/'.$id]);
}
function serveMedia(string $id,string $method): never {
 $q=db()->prepare('SELECT mime,bytes FROM cms_media WHERE id=?');$q->execute([$id]);$r=$q->fetch();$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif','video/mp4'=>'mp4'];if(!$r||!isset($types[$r['mime']])){http_response_code(404);exit;}
 $path=UPLOAD_DIR.'/'.$id.'.'.$types[$r['mime']];if(!is_file($path)){http_response_code(404);exit;}$size=filesize($path);$start=0;$end=$size-1;header('Content-Type: '.$r['mime']);header('Cache-Control: public, max-age=86400, immutable');header('Accept-Ranges: bytes');$range=$_SERVER['HTTP_RANGE']??'';
 if($range!==''){if(!preg_match('/^bytes=(\d*)-(\d*)$/D',$range,$m)||($m[1]===''&&$m[2]==='')){header('Content-Range: bytes */'.$size);http_response_code(416);exit;}if($m[1]===''){$start=max(0,$size-(int)$m[2]);}else{$start=(int)$m[1];if($m[2]!=='')$end=min($end,(int)$m[2]);}if($start>$end||$start>=$size){header('Content-Range: bytes */'.$size);http_response_code(416);exit;}http_response_code(206);header('Content-Range: bytes '.$start.'-'.$end.'/'.$size);}
 $length=$end-$start+1;header('Content-Length: '.$length);if($method==='HEAD')exit;$f=fopen($path,'rb');fseek($f,$start);while($length>0&&!feof($f)){ $chunk=fread($f,min($length,65536));if($chunk===false||$chunk==='')break;echo $chunk;$length-=strlen($chunk);}fclose($f);exit;
}
$method=$_SERVER['REQUEST_METHOD']??'GET';$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
try {
 if($path==='/setup'||$path==='/setup/')setup($method);
 if($path==='/content.js'&&in_array($method,['GET','HEAD'],true)){header('Content-Type: application/javascript; charset=utf-8');if($method==='GET'){try{$c=installed()?data('published'):readData('seed.json');}catch(PDOException|RuntimeException $e){$c=readData('seed.json');}echo 'window.HOSPITAL = '.json_encode($c,JFLAGS|JSON_HEX_TAG).';';}exit;}
 if(preg_match('~^/media/([a-f0-9]{32})$~D',$path,$m)&&in_array($method,['GET','HEAD'],true))serveMedia($m[1],$method);
 if(in_array($path,['/admin','/admin/','/admin/login'],true)&&in_array($method,['GET','HEAD'],true)){header('Content-Type: text/html; charset=utf-8');header("Content-Security-Policy: default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' https: data:; media-src 'self' https:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'");if($method==='GET')readfile(PRIVATE_DIR.'/admin.html');exit;}
 if(str_starts_with($path,'/api/admin/')){
  if(!in_array($method,['GET','POST'],true))fail('Method not allowed',405);
  if($method==='POST')csrf();
  if(!installed())fail('Complete /setup before signing in.',503);
  if($path==='/api/admin/login'&&$method==='POST'){checkRate();$b=readJson(4096);$user=is_object($b)?($b->user??null):null;$pw=is_object($b)?($b->password??null):null;$r=db()->query('SELECT username,password_hash FROM cms_admin WHERE id=1')->fetch();if(!is_string($user)||!is_string($pw)||strlen($pw)>128||!$r||!hash_equals($r['username'],$user)||!password_verify($pw,$r['password_hash']))fail('Invalid credentials',401);beginSession();session_regenerate_id(true);$_SESSION=['admin'=>true,'expires'=>time()+3600];session_write_close();sendJson(['ok'=>true]);}
  adminRequired();
  if($path==='/api/admin/logout'&&$method==='POST'){$_SESSION=[];session_destroy();setcookie('HOSPITAL_ADMIN','',['expires'=>time()-3600,'path'=>'/','secure'=>true,'httponly'=>true,'samesite'=>'Strict']);sendJson(['ok'=>true]);}
  if($path==='/api/admin/data'&&$method==='GET')sendJson(data('draft'));
  if(in_array($path,['/api/admin/draft','/api/admin/publish'],true)&&$method==='POST'){$x=readJson();validate($x,readData('defaults.json'));$body=json_encode($x,JFLAGS);$p=db();$p->beginTransaction();try{writeData('draft',$body);if($path==='/api/admin/publish')writeData('published',$body);$p->commit();}catch(Throwable $e){$p->rollBack();throw $e;}sendJson(['ok'=>true]);}
  if($path==='/api/admin/upload'&&$method==='POST')upload();fail('Not found',404);
 }
 if(in_array($method,['GET','HEAD'],true)&&($path==='/'||$path==='/index.php'||$path==='/index.html'||preg_match('~^/(home|about|departments|services|infrastructure|gallery|contact|visits)/?$~D',$path))){header('Content-Type: text/html; charset=utf-8');if($method==='GET')readfile(__DIR__.'/public/index.html');exit;}
 http_response_code(404);header('Content-Type: text/plain; charset=utf-8');echo 'Not found';
}catch(InvalidArgumentException|JsonException $e){fail($e->getMessage(),400);}catch(Throwable $e){error_log('Hospital CMS: '.get_class($e));if($path==='/setup'||$path==='/setup/')setupPage('Database connection or initialization failed. Check private/config.php and MySQL permissions.');fail('Server configuration or database error. Check hosting settings.',500);}
